//! Staged, mechanism-only B/retention over an actual Fresh Bootstrap T.
//! Registration precedes T. Neither constructor runs PositiveFixture's
//! auxiliary Evaluation/Model path. The two real Trainer servers remain owned
//! by OriginalTrainingPeers outside this fixture and are explicitly joined.
use super::*;
use crate::OriginalCellEvaluationHostV1;
use crate::OriginalCellEvaluationPanelOwnerV1;
use crate::OriginalCellEvaluationReceiptConfigV1;
use crate::OriginalCellEvaluationReceiptOwnerV1;
use crate::OriginalCellEvaluationSigningConfigV1;
use crate::OriginalCellQ24CandidateMaterialV1;
use crate::OriginalCellQ24MaterialCommandReceiptV1;
use crate::OriginalCellQ24MaterialReceiptConfigV1;
use crate::OriginalCellQ24TrainingCommandReceiptV1;
use crate::neuron_cell_evaluation::tests::original_provider::panel_members::PanelMemberFixture;
use material::evaluation_provider::DecisionBinding;

type Panel = OriginalCellEvaluationPanelOwnerV1<
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
>;

/// A borrowed view of original completed inputs, not another owner or signer.
/// Candidate is opaque production readback material; both manifests are built
/// from its actual model and the original loaded baseline, without prior E.
pub(in super::super) struct CompletedTrainingInputs<'a> {
    material: &'a OriginalCellQ24MaterialReceiptConfigV1,
    previous: &'a CircuitTaskSourcePublicationV1,
    training: LearningIterationSnapshotV1,
    training_evidence: &'a SignedLearningEvidenceV1,
    baseline: Digest32,
    candidate: Digest32,
    manifests: [CellBackendManifestV2; 2],
    credentials: &'a material::Credentials,
}

impl<'a> CompletedTrainingInputs<'a> {
    pub(in super::super) fn from_original_completion(
        material: &'a OriginalCellQ24MaterialReceiptConfigV1,
        dataset: &OriginalCellQ24MaterialCommandReceiptV1,
        training: &'a OriginalCellQ24TrainingCommandReceiptV1,
        candidate: &OriginalCellQ24CandidateMaterialV1,
        baseline: &LoadedCellQ24ModelV1,
        previous: &'a CircuitTaskSourcePublicationV1,
        source_a: &crate::CircuitTaskSourceInputV1,
        config_a: &codex_hepta_neuron::CellGenerationConfigV2,
        credentials: &'a material::Credentials,
    ) -> anyhow::Result<Self> {
        OriginalCellQ24MaterialCommandReceiptV1::require_original_dataset_context(dataset, material)?;
        anyhow::ensure!(material.initial.receipts.is_empty() && dataset.snapshot().receipts.len() == 2);
        anyhow::ensure!(candidate.receipt() == training.receipt());
        anyhow::ensure!(candidate.attestation() == training.attestation());
        anyhow::ensure!(candidate.authority() == AuthorityPosture::DENY_ALL);
        anyhow::ensure!(baseline.components() == &material.initial.request.selected_bundle.components);
        anyhow::ensure!(previous.input() == source_a);
        anyhow::ensure!(source_a.scope.run_id == material.initial.request.source_run_id);
        anyhow::ensure!(source_a.objective_digest == material.initial.request.envelope.objective_digest);
        anyhow::ensure!(previous.history_digest().as_str().parse::<Digest32>()?
            == material.initial.request.completed_task_receipt);
        anyhow::ensure!(credentials.generator.principal.principal_id == material.initial.owners.trainer);
        anyhow::ensure!(credentials.evaluator.principal.principal_id == material.initial.owners.evaluator);
        let mut cut = LearningIterationCoordinatorV1::from_snapshot(dataset.snapshot().clone())?;
        cut.record(training.receipt().clone(), training.receipt().observed_unix_seconds)?;
        anyhow::ensure!(cut.next_stage() == Some(LearningIterationStageV1::Evaluation));
        anyhow::ensure!(cut.snapshot().receipts.len() == 3);
        let baseline_bundle = &material.initial.request.selected_bundle;
        let baseline_definition = support::definition(baseline, baseline_bundle)?;
        let baseline_manifest = support::configuration(
            baseline, baseline_bundle, &baseline_definition, source_a, 1,
        )?.manifest;
        anyhow::ensure!(baseline_manifest == config_a.manifest);
        let candidate_definition = support::definition(candidate.model(), candidate.bundle())?;
        let candidate_manifest = support::configuration(
            candidate.model(), candidate.bundle(), &candidate_definition, source_a, 2,
        )?.manifest;
        Ok(Self {
            material,
            previous,
            training: cut.snapshot().clone(),
            training_evidence: training.attestation(),
            baseline: baseline_bundle.digest()?,
            candidate: candidate.bundle().digest()?,
            manifests: [candidate_manifest, baseline_manifest],
            credentials,
        })
    }
}

/// Created before Material/T; its frozen registration is supplied to the
/// original initial request. No later receipt or profile is rewritten.
pub(in super::super) struct PreparedBPanel {
    primary: BFixture,
    retention: BFixture,
    registration: crate::OriginalCellEvaluationPanelRegistrationV1,
}

impl PreparedBPanel {
    pub(in super::super) fn new(objective: Digest32, trust_time: u64) -> anyhow::Result<Self> {
        let primary = BFixture::new("original-B", objective, trust_time)?;
        let retention = BFixture::new("original-retention", objective, trust_time)?;
        let registration = crate::OriginalCellEvaluationPanelRegistrationV1::new(
            primary.task()?, vec![retention.task()?],
        )?;
        Ok(Self { primary, retention, registration })
    }

    pub(in super::super) fn registration(&self) -> &crate::OriginalCellEvaluationPanelRegistrationV1 {
        &self.registration
    }

    pub(in super::super) fn complete<'a>(
        self,
        input: &'a CompletedTrainingInputs<'a>,
        primary_trainer: LearningIterationEvidenceClientV1,
        retention_trainer: LearningIterationEvidenceClientV1,
    ) -> impl std::future::Future<Output = anyhow::Result<CompletedBPanel>> + 'a {
        Box::pin(async move {
            let Self { mut primary, mut retention, registration } = self;
            anyhow::ensure!(input.material.initial.request.evaluation_profile == registration.evaluation_profile());
            anyhow::ensure!(primary.rule.objective_digest == input.material.initial.request.envelope.objective_digest);
            anyhow::ensure!(primary.at == retention.at);
            let at = primary.at;
            // The original retention result is completed first and enters the
            // primary's signed declaration. Equal supported policies continue
            // to produce the original honest Ineligible result.
            let mut retention_member = complete_member(
                &mut retention, input, &registration, Vec::new(), retention_trainer,
            ).await?;
            let digests = vec![retention_member.qualification.product().evidence_digest];
            let mut primary_member = complete_member(
                &mut primary, input, &registration, digests, primary_trainer,
            ).await?;
            let config = &primary_member.config;
            let receipt_config = OriginalCellEvaluationReceiptConfigV1 {
                training: config.training.clone(),
                scope: config.scope.clone(),
                plan: config.plan.clone(),
                signing: OriginalCellEvaluationSigningConfigV1 {
                    plan: config.plan.product_plan().clone(),
                    execution_namespace: config.execution_namespace,
                    signer: input.credentials.evaluator.clone(),
                    verifier: config.verifier.clone(),
                    maximum_signature_lifetime_seconds: 600,
                },
            };
            let panel = Panel::from_original_owners(
                registration,
                primary_member.take_original_member(),
                vec![retention_member.take_original_member()],
            )?;
            let directory = tempfile::tempdir_in(std::env::temp_dir().canonicalize()?)?;
            let mut result = CompletedBPanel {
                host: None, config: receipt_config, at, primary, retention,
                primary_member, retention_member, directory,
            };
            let (file, witness) = result.files(true)?;
            let evaluator = OriginalCellEvaluationReceiptOwnerV1::create(
                file, witness, result.config.clone(), SigningKey::from_bytes(&[42; 32]),
            )?;
            let mut host = evaluator.into_original_evaluation_host(panel)?;
            // This remains the existing explicit B clock fixture. It is not a
            // claim of deployed task timing or independently obtained data.
            host.fixture_original_clock(at)?;
            result.host = Some(Arc::new(host));
            Ok(result)
        })
    }
}

async fn complete_member(
    b: &mut BFixture,
    input: &CompletedTrainingInputs<'_>,
    registration: &crate::OriginalCellEvaluationPanelRegistrationV1,
    retention_receipt_digests: Vec<Digest32>,
    trainer: LearningIterationEvidenceClientV1,
) -> anyhow::Result<PanelMemberFixture> {
    b.populate_from_original_training(
        input.previous, input.baseline, input.candidate,
        ObservationMode::Complete, false, DecisionBinding::ExactSource,
    ).await?;
    let config = b.config_from_original_training(
        input.training.clone(), &input.material.scope, input.training_evidence,
        &input.material.verifier, registration,
    )?;
    let cohort = CohortAt::read(b.owners(), config, b.at)?;
    let runner = ProviderPlanFixture::for_panel(
        &cohort.original, &b.rule, &input.training, input.manifests.clone(),
    )?;
    let provider = cohort.consume(runner.plan.clone())?;
    Box::pin(PanelMemberFixture::complete_from_original_trainer(
        runner, provider, &input.material.initial, input.training.clone(),
        input.training_evidence.clone(), &input.material.scope,
        &input.credentials.generator, &input.credentials.evaluator,
        input.material.verifier.clone(), retention_receipt_digests, trainer,
    )).await
}

pub(in super::super) struct CompletedBPanel {
    pub(in super::super) host: Option<Arc<OriginalCellEvaluationHostV1>>,
    pub(in super::super) config: OriginalCellEvaluationReceiptConfigV1,
    pub(in super::super) at: u64,
    primary: BFixture,
    retention: BFixture,
    primary_member: PanelMemberFixture,
    retention_member: PanelMemberFixture,
    directory: tempfile::TempDir,
}

impl CompletedBPanel {
    fn files(&self, create: bool) -> anyhow::Result<(File, FileAnchorWitnessStore)> {
        let root = self.directory.path();
        let file = opened(root, "original-evaluation", create)?;
        let witness = original_witness(
            root, "original-evaluation-witness", &self.config.scope,
            self.config.signing.verifier.objective_digest(), create,
        )?;
        Ok((file, witness))
    }

    pub(in super::super) fn original_files(&self) -> anyhow::Result<[Vec<u8>; 2]> {
        Ok([
            fs::read(self.directory.path().join("original-evaluation"))?,
            fs::read(self.directory.path().join("original-evaluation-witness"))?,
        ])
    }

    pub(in super::super) fn upstream_files(&self) -> anyhow::Result<Vec<Vec<u8>>> {
        let mut result = self.primary_member.bytes()?;
        result.extend(self.retention_member.bytes()?);
        result.extend(self.primary.all_source_bytes()?);
        result.extend(self.retention.all_source_bytes()?);
        result.extend(self.host.as_ref().ok_or_else(|| anyhow::anyhow!("original host retained"))?
            .fixture_original_cohort_files()?);
        Ok(result)
    }

    pub(in super::super) fn recover(&mut self) -> anyhow::Result<()> {
        let host = Arc::try_unwrap(self.host.take().ok_or_else(|| anyhow::anyhow!("original host retained"))?)
            .map_err(|_| anyhow::anyhow!("all original Evaluation services must be joined before recovery"))?;
        let panel = host.fixture_take_original_panel()?;
        let (file, witness) = self.files(false)?;
        let evaluator = OriginalCellEvaluationReceiptOwnerV1::recover(
            file, witness, self.config.clone(), SigningKey::from_bytes(&[42; 32]),
        )?;
        let mut host = evaluator.into_original_evaluation_host(panel)?;
        host.fixture_original_clock(self.at)?;
        self.host = Some(Arc::new(host));
        Ok(())
    }

    /// All external service futures must have joined before this point; the
    /// outside OriginalTrainingPeers is finished only after these clients drop.
    pub(in super::super) fn finish(mut self) -> anyhow::Result<()> {
        anyhow::ensure!(self.host.as_ref().is_some_and(|host| Arc::strong_count(host) == 1),
            "all original Evaluation services must be joined");
        drop(self.host.take());
        self.primary_member.finish_with_external_trainer()?;
        self.retention_member.finish_with_external_trainer()?;
        Ok(())
    }
}

//! Mechanism-only member construction using actual B providers and original
//! execution/Qualification files. Product declarations, costs and signing keys
//! are explicit fixtures. No synthetic provider supplies the released rows.
use std::sync::Arc;
use std::time::SystemTime;
use std::time::UNIX_EPOCH;

use codex_hepta_learning_artifacts::FrozenLearningScopeV2;
use codex_hepta_learning_ledger::LearningEvidenceVerifierV1;
use codex_hepta_learning_ledger::SignedLearningEvidenceV1;
use codex_hepta_learning_ledger::TrustedLearningSignerV1;
use ed25519_dalek::SigningKey;
use pretty_assertions::assert_eq;

use super::*;
use crate::OriginalCellEvaluationExecutionOwnerV1;
use crate::OriginalCellEvaluationExecutionStoreV1;
use crate::OriginalCellEvaluationPanelMemberOwnersV1;
use crate::OriginalCellEvaluationQualificationConfigV1;
use crate::OriginalCellEvaluationQualificationOwnerV1;
use crate::OriginalCellEvaluationQualificationSourcesV1;
use crate::OriginalCellEvaluationSigningConfigV1;
use crate::circuit_original_evaluation_provider::test_access::ProviderAt;
use crate::learning_iteration_evidence_client::fixture_original_receipt_client_until_close;
use crate::neuron_cell_evaluation::tests::original_model_selection::sign_product;
use crate::neuron_cell_evaluation::tests::original_model_selection::witness;

type Member = OriginalCellEvaluationPanelMemberOwnersV1<
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
    FileAnchorWitnessStore,
>;
type PeerThread = std::thread::JoinHandle<anyhow::Result<usize>>;

pub(crate) struct PanelMemberFixture {
    member: Option<Member>,
    pub(crate) qualification: CellEvaluationQualificationV1,
    pub(crate) config: OriginalCellEvaluationQualificationConfigV1,
    initial: LearningIterationSnapshotV1,
    thread: Option<PeerThread>,
    _execution_signer: OriginalCellEvaluationExecutionOwnerV1<FileAnchorWitnessStore>,
    directory: tempfile::TempDir,
}

fn now() -> anyhow::Result<u64> {
    Ok(SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs())
}

impl PanelMemberFixture {
    pub(crate) fn complete<'a>(
        original_plan: ProviderPlanFixture,
        provider: ProviderAt,
        initial: &'a LearningIterationSnapshotV1,
        training: LearningIterationSnapshotV1,
        training_evidence: SignedLearningEvidenceV1,
        scope: &'a FrozenLearningScopeV2,
        generator: &'a TrustedLearningSignerV1,
        evaluator: &'a TrustedLearningSignerV1,
        verifier: LearningEvidenceVerifierV1,
        retention_receipt_digests: Vec<Digest32>,
    ) -> impl std::future::Future<Output = anyhow::Result<Self>> + 'a {
        Self::complete_with_trainer(
            original_plan, provider, initial, training, training_evidence,
            scope, generator, evaluator, verifier, retention_receipt_digests,
            None,
        )
    }

    /// The caller retains and joins this real Trainer's server. No retained
    /// signature responder is constructed on the fresh-provider path.
    pub(crate) fn complete_from_original_trainer<'a>(
        original_plan: ProviderPlanFixture,
        provider: ProviderAt,
        initial: &'a LearningIterationSnapshotV1,
        training: LearningIterationSnapshotV1,
        training_evidence: SignedLearningEvidenceV1,
        scope: &'a FrozenLearningScopeV2,
        generator: &'a TrustedLearningSignerV1,
        evaluator: &'a TrustedLearningSignerV1,
        verifier: LearningEvidenceVerifierV1,
        retention_receipt_digests: Vec<Digest32>,
        trainer: crate::LearningIterationEvidenceClientV1,
    ) -> impl std::future::Future<Output = anyhow::Result<Self>> + 'a {
        Self::complete_with_trainer(
            original_plan, provider, initial, training, training_evidence,
            scope, generator, evaluator, verifier, retention_receipt_digests,
            Some(trainer),
        )
    }

    async fn complete_with_trainer(
        original_plan: ProviderPlanFixture,
        mut provider: ProviderAt,
        initial: &LearningIterationSnapshotV1,
        training: LearningIterationSnapshotV1,
        training_evidence: SignedLearningEvidenceV1,
        scope: &FrozenLearningScopeV2,
        generator: &TrustedLearningSignerV1,
        evaluator: &TrustedLearningSignerV1,
        verifier: LearningEvidenceVerifierV1,
        retention_receipt_digests: Vec<Digest32>,
        original_trainer: Option<crate::LearningIterationEvidenceClientV1>,
    ) -> anyhow::Result<Self> {
        let ProviderPlanFixture {
            mut fixture,
            plan,
            execution_namespace,
        } = original_plan;
        let root = fixture.directory.path().to_path_buf();
        let context = ProductQualificationContextV1 {
            generator: generator.principal.clone(),
            evaluator: evaluator.principal.clone(),
            retention_receipt_digests,
            unlearning_receipt_digest: Digest32::ZERO,
        };
        let signing = OriginalCellEvaluationSigningConfigV1 {
            plan: plan.product_plan().clone(),
            execution_namespace,
            signer: evaluator.clone(),
            verifier: verifier.clone(),
            maximum_signature_lifetime_seconds: 600,
        };
        let mut execution_signer = OriginalCellEvaluationExecutionOwnerV1::create(
            file(&root.join("panel-execution-signature")),
            witness(
                &root,
                "panel-execution-signature-witness",
                scope,
                verifier.objective_digest(),
            )?,
            signing.clone(),
            SigningKey::from_bytes(&[42; 32]),
        )?;
        let mut executions = OriginalCellEvaluationExecutionStoreV1::create(
            file(&root.join("panel-executions")),
            witness(
                &root,
                "panel-execution-witness",
                scope,
                verifier.objective_digest(),
            )?,
            digest(&format!(
                "explicit-panel-raw-execution:{}",
                plan.product_plan().frozen_plan.plan_id
            )),
        )?;
        let clock = || now().map_err(|_| ProductProviderErrorV1::Unavailable);
        let receipt = fixture.runner.evaluate_or_readback(
            &plan,
            CellEvaluationJournalsV1 {
                candidate: &fixture.candidate,
                fixed_expert: &fixture.fixed,
            },
            &ProductEvaluationExecutionRequestV1 {
                plan: plan.product_plan(),
                candidate_plan: &fixture.candidate_temporal,
                baseline_plan: &fixture.baseline_temporal,
                evaluator: &context.evaluator,
                verifier: &verifier,
                clock: &clock,
            },
            &mut provider,
            &mut executions,
            &mut execution_signer,
        )?;
        assert_eq!((provider.manifest_calls, provider.releases), (1, 1));
        assert_eq!((fixture.provider.calls, fixture.provider.releases), (0, 0));
        assert_eq!(receipt.temporal().candidate.estimate.point.rows, 2);
        assert_eq!(
            receipt.temporal().candidate.estimate.point.doubly_robust,
            receipt.temporal().baseline.estimate.point.doubly_robust
        );
        let cohort = provider.into_original_readback()?;
        let bundle = fixture.runner.qualification_bundle(&receipt, &context)?;
        let issued_at = now()?;
        anyhow::ensure!(issued_at >= training.receipts[2].observed_unix_seconds);
        let evidence = SignedEvaluationEvidenceV1 {
            generator_plan: sign_product(
                &verifier,
                generator,
                41,
                bundle.frozen_plan.plan_digest.as_array(),
                issued_at,
            ),
            evaluator_bundle: sign_product(
                &verifier,
                evaluator,
                42,
                &evaluation_signing_payload_v2(&bundle, &plan.product_plan().metric_roles)?,
                issued_at,
            ),
        };
        let (_, execution_evidence) = fixture.runner.readback_completed_evidence(
            &plan,
            CellEvaluationJournalsV1 {
                candidate: &fixture.candidate,
                fixed_expert: &fixture.fixed,
            },
            &ProductEvaluationExecutionRequestV1 {
                plan: plan.product_plan(),
                candidate_plan: &fixture.candidate_temporal,
                baseline_plan: &fixture.baseline_temporal,
                evaluator: &context.evaluator,
                verifier: &verifier,
                clock: &clock,
            },
            &mut executions,
        )?;
        assert_eq!(
            execution_evidence.attestation(),
            &execution_signer.readback()?.1
        );
        let config = OriginalCellEvaluationQualificationConfigV1 {
            training: training.clone(),
            scope: scope.clone(),
            plan: plan.clone(),
            execution_namespace,
            qualification_namespace: digest(&format!(
                "explicit-panel-Qualification:{}",
                plan.product_plan().frozen_plan.plan_id,
            )),
            context,
            training_evidence: training_evidence.clone(),
            product_evidence: evidence,
            execution_evidence,
            verifier: verifier.clone(),
        };
        let mut qualification_owner = OriginalCellEvaluationQualificationOwnerV1::create(
            file(&root.join("panel-qualification")),
            witness(
                &root,
                "panel-qualification-witness",
                scope,
                verifier.objective_digest(),
            )?,
            config.clone(),
        )?;
        let (trainer, thread) = match original_trainer {
            Some(trainer) => (trainer, None),
            None => {
                let (trainer, thread) = fixture_original_receipt_client_until_close(
                    initial.clone(),
                    training.receipts[2].clone(),
                    verifier,
                    training_evidence,
                )?;
                (trainer, Some(thread))
            }
        };
        // Do not inline the original Qualification readback state into the
        // surrounding member setup, which owns both physical runner journals.
        let qualification = Box::pin(qualification_owner.qualify_or_readback(
            OriginalCellEvaluationQualificationSourcesV1 {
                runner: &mut fixture.runner,
                journals: CellEvaluationJournalsV1 {
                    candidate: &fixture.candidate,
                    fixed_expert: &fixture.fixed,
                },
                candidate_plan: &fixture.candidate_temporal,
                baseline_plan: &fixture.baseline_temporal,
                executions: &mut executions,
                trainer: &trainer,
            },
        ))
        .await?;
        // The original evaluator computes this negative result from the equal
        // supported policies. It is never rewritten to fabricate improvement.
        assert_eq!(
            qualification.product().decision.decision.disposition,
            IndependentEvaluationDispositionV1::Ineligible
        );
        let member = Member {
            qualification: qualification_owner,
            runner: fixture.runner,
            candidate: fixture.candidate,
            fixed_expert: fixture.fixed,
            candidate_plan: fixture.candidate_temporal,
            baseline_plan: fixture.baseline_temporal,
            executions,
            trainer: Arc::new(trainer),
            cohort,
        };
        Ok(Self {
            member: Some(member),
            qualification,
            config,
            initial: initial.clone(),
            thread,
            _execution_signer: execution_signer,
            directory: fixture.directory,
        })
    }

    pub(crate) fn take_original_member(&mut self) -> Member {
        self.member
            .take()
            .expect("one original panel member transfer")
    }

    pub(crate) fn bytes(&self) -> anyhow::Result<Vec<Vec<u8>>> {
        [
            "original-B-candidate-cost",
            "original-B-candidate-cost-witness",
            "original-B-baseline-cost",
            "original-B-baseline-cost-witness",
            "holdout",
            "panel-executions",
            "panel-execution-witness",
            "panel-execution-signature",
            "panel-execution-signature-witness",
            "panel-qualification",
            "panel-qualification-witness",
        ]
        .into_iter()
        .map(|name| Ok(std::fs::read(self.directory.path().join(name))?))
        .collect()
    }

    pub(crate) fn renewed_training_peer(
        &mut self,
        evidence: SignedLearningEvidenceV1,
    ) -> anyhow::Result<()> {
        let member = self.member.as_mut().expect("not transferred");
        let (client, thread) = fixture_original_receipt_client_until_close(
            self.initial.clone(),
            self.config.training.receipts[2].clone(),
            self.config.verifier.clone(),
            evidence,
        )?;
        drop(std::mem::replace(&mut member.trainer, Arc::new(client)));
        let prior = self.thread.replace(thread).expect("original peer");
        assert_eq!(prior.join().expect("original Qualification Trainer")?, 2);
        Ok(())
    }

    pub(crate) fn finish(mut self) -> anyhow::Result<usize> {
        drop(self.member.take());
        self.thread
            .take()
            .expect("retained original peer")
            .join()
            .expect("original panel Trainer transport")
    }

    /// Drop the actual member's client before the outside fixture joins the
    /// original Trainer server. This does not report a fabricated frame count.
    pub(crate) fn finish_with_external_trainer(mut self) -> anyhow::Result<()> {
        anyhow::ensure!(self.thread.is_none(), "original Trainer server remains externally owned");
        drop(self.member.take());
        Ok(())
    }
}

